{
  "template": "trigger"
}

namespace readings;
table Table { x:[double]; y:[double]; }
table Outputs { data:Table (required); }
root_type Outputs;

{
  pkgs,
  inputs,
  params,
}:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "params": [
    {
      "name": "offset",
      "type": "double",
      "data": 0
    }
  ],
  "recordIO": true
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "line",
        "scatter",
        "histogram"
      ]
    }
  ]
}

attribute "tsugumi";
namespace visualization;
table Files { value:string; }
table Outputs { figure:Files (required, tsugumi: "directory"); }
root_type Outputs;

{
  pkgs,
  inputs,
  params,
}:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [
      ps.numpy
      ps.matplotlib
    ];
    fonts = [ pkgs.ipaexfont ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "data"
    }
  ],
  "filesystem": true,
  "recordIO": true,
  "params": [
    {
      "name": "data_path",
      "type": "string",
      "data": ""
    },
    {
      "name": "file",
      "type": "string",
      "data": "data.csv"
    },
    {
      "name": "x",
      "type": "string",
      "data": "x"
    },
    {
      "name": "y",
      "type": "string",
      "data": "y"
    },
    {
      "name": "series",
      "type": "string",
      "data": ""
    },
    {
      "name": "title",
      "type": "string",
      "data": "Line chart"
    },
    {
      "name": "x_label",
      "type": "string",
      "data": ""
    },
    {
      "name": "y_label",
      "type": "string",
      "data": ""
    },
    {
      "name": "width",
      "type": "double",
      "data": 7
    },
    {
      "name": "height",
      "type": "double",
      "data": 4
    },
    {
      "name": "dpi",
      "type": "uint64",
      "data": 120
    },
    {
      "name": "theme",
      "type": "string",
      "data": "light"
    },
    {
      "name": "max_points",
      "type": "uint64",
      "data": 5000
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "figure"
}

